#include <stdint.h>
#include <string.h>
#include NVIM_BASE64_C

// Equivalence proof for tool patch 'load64' (generated by tool_patches.py).
void harness(void) {
  // The statements read only s[src_i .. src_i + 7], so covering every value of
  // those bytes covers every call. No assumptions: buf is fully nondeterministic.
  uint8_t buf[8];
  const size_t src_i = 0;
  const uint8_t *s = buf;
  uint64_t before, after;
  {
    uint64_t bits_h;
    memcpy(&bits_h, &s[src_i], sizeof(uint64_t));
    const uint64_t bits_be = htobe64(bits_h);
    before = bits_be;
  }
  {
    const uint64_t bits_be = ((uint64_t)s[src_i] << 56) | ((uint64_t)s[src_i + 1] << 48)
      | ((uint64_t)s[src_i + 2] << 40) | ((uint64_t)s[src_i + 3] << 32)
      | ((uint64_t)s[src_i + 4] << 24) | ((uint64_t)s[src_i + 5] << 16)
      | ((uint64_t)s[src_i + 6] << 8) | (uint64_t)s[src_i + 7];
    after = bits_be;
  }
  __CPROVER_assert(before == after, "load64: rewrite equals original");
}
